func (c ChartView) build() swiftui.View {
	if c.builder == nil {
		return swiftui.ViewFromPointer(0)
	}
	c.builder.once.Do(func() {
		data, err := json.Marshal(c.builder.toSpec())
		if err != nil || len(data) == 0 {
			return
		}
		ptr := _CHBuildChart((*byte)(&data[0]), int32(len(data)))
		c.builder.view = swiftui.ViewFromPointer(ptr)
	})
	return c.builder.view
}

func (c ChartView) viewPtr() uintptr { return c.build().Pointer() }

// Pointer returns the underlying Swift pointer.
func (c ChartView) Pointer() uintptr { return c.build().Pointer() }

// View returns the underlying SwiftUI view.
func (c ChartView) View() swiftui.View { return c.build() }

// AsView returns the underlying SwiftUI view.
func (c ChartView) AsView() swiftui.View { return c.build() }

// Frame applies a SwiftUI frame to the built chart view.
func (c ChartView) Frame(width, height float64) swiftui.View {
	return c.build().Frame(width, height)
}

