func (v AxisValues) toSpec() axisValuesSpec {
	spec := axisValuesSpec{
		Kind:            int32(v.kind),
		Step:            v.step,
		Unit:            int32(v.unit),
		Count:           v.count,
		DesiredCount:    v.desiredCount,
		RoundLowerBound: v.roundLowerBound,
		RoundUpperBound: v.roundUpperBound,
	}
	if len(v.values) > 0 {
		spec.Values = make([]valueSpec, len(v.values))
		for i, value := range v.values {
			spec.Values[i] = value.toSpec()
		}
	}
	return spec
}

