func copyMarkMods(mods []markMod) []markMod {
	return append([]markMod(nil), mods...)
}

func copyMarkChildren(children []Mark) []Mark {
	return append([]Mark(nil), children...)
}

func stripMarkMods(m Mark, kinds ...markModKind) Mark {
	if len(m.mods) == 0 {
		return m
	}
	drop := map[markModKind]bool{}
	for _, kind := range kinds {
		drop[kind] = true
	}
	filtered := make([]markMod, 0, len(m.mods))
	for _, mod := range m.mods {
		if !drop[mod.kind] {
			filtered = append(filtered, mod)
		}
	}
	m.mods = filtered
	return m
}

func hasMarkMod(m Mark, kind markModKind) bool {
	for _, mod := range m.mods {
		if mod.kind == kind {
			return true
		}
	}
	return false
}

func annotationDeclutterLimit(m Mark) (int, bool) {
	for _, mod := range m.mods {
		if mod.kind == modAnnotationDeclutterLatest {
			if mod.intV < 1 {
				return 1, true
			}
			return int(mod.intV), true
		}
	}
	return 0, false
}

func annotationDeclutterDistance(m Mark) (float64, float64, bool) {
	for _, mod := range m.mods {
		if mod.kind == modAnnotationDeclutterDistance {
			return mod.floatX, mod.floatY, true
		}
	}
	return 0, 0, false
}

func annotationDataOffset(m Mark) (float64, float64, bool) {
	for _, mod := range m.mods {
		if mod.kind == modAnnotationDataOffset {
			return mod.floatX, mod.floatY, true
		}
	}
	return 0, 0, false
}

func annotationCollisionMode(m Mark) AnnotationCollisionMode {
	for _, mod := range m.mods {
		if mod.kind == modAnnotationCollision {
			return AnnotationCollisionMode(mod.intV)
		}
	}
	return AnnotationCollisionAutomatic
}

func annotationPriority(m Mark) int {
	for _, mod := range m.mods {
		if mod.kind == modAnnotationPriority {
			return int(mod.intV)
		}
	}
	return 0
}

type annotationCoordState struct {
	xCategories map[string]float64
	yCategories map[string]float64
}

type annotationPoint struct {
	x float64
	y float64
}

type keptAnnotation struct {
	point    annotationPoint
	index    int
	priority int
}

func numericValue(v Value, cats map[string]float64) (float64, bool) {
	switch v.kind {
	case valueCategory:
		if cats == nil {
			return 0, false
		}
		if value, ok := cats[v.category]; ok {
			return value, true
		}
		value := float64(len(cats))
		cats[v.category] = value
		return value, true
	case valueInteger:
		return float64(v.integer), true
	case valueNumber:
		return v.number, true
	case valueTime:
		return float64(v.timestamp.UnixMilli()) / 1000.0, true
	default:
		return 0, false
	}
}

func annotationPointForMark(m Mark, state *annotationCoordState) (annotationPoint, bool) {
	xDim, okX := findDim(m.dims, dimX)
	yDim, okY := findDim(m.dims, dimY)
	if !okX || !okY {
		return annotationPoint{}, false
	}
	x, okX := numericValue(xDim.value, state.xCategories)
	y, okY := numericValue(yDim.value, state.yCategories)
	if !okX || !okY {
		return annotationPoint{}, false
	}
	if dx, dy, ok := annotationDataOffset(m); ok {
		x += dx
		y += dy
	}
	return annotationPoint{x: x, y: y}, true
}

func annotationOverlapIndices(point annotationPoint, kept []keptAnnotation, minX, minY float64) []int {
	if minX <= 0 && minY <= 0 {
		return nil
	}
	var overlaps []int
	for i, other := range kept {
		dx := point.x - other.point.x
		if dx < 0 {
			dx = -dx
		}
		dy := point.y - other.point.y
		if dy < 0 {
			dy = -dy
		}
		xClose := minX <= 0 || dx < minX
		yClose := minY <= 0 || dy < minY
		if xClose && yClose {
			overlaps = append(overlaps, i)
		}
	}
	return overlaps
}

func (b *chartBuilder) collisionThresholds() (float64, float64) {
	minX, minY := 0.1, 0.1
	if b.xDomain != nil {
		switch b.xDomain.kind {
		case domainInteger:
			if span := float64(b.xDomain.maxInt - b.xDomain.minInt); span > 0 {
				minX = span * 0.015
			}
		case domainNumber:
			if span := b.xDomain.maxNumber - b.xDomain.minNumber; span > 0 {
				minX = span * 0.015
			}
		case domainTime:
			if span := b.xDomain.endTime.Sub(b.xDomain.startTime).Seconds(); span > 0 {
				minX = span * 0.015
			}
		}
	}
	if b.yDomain != nil {
		switch b.yDomain.kind {
		case domainInteger:
			if span := float64(b.yDomain.maxInt - b.yDomain.minInt); span > 0 {
				minY = span * 0.02
			}
		case domainNumber:
			if span := b.yDomain.maxNumber - b.yDomain.minNumber; span > 0 {
				minY = span * 0.02
			}
		case domainTime:
			if span := b.yDomain.endTime.Sub(b.yDomain.startTime).Seconds(); span > 0 {
				minY = span * 0.02
			}
		}
	}
	return minX, minY
}

func addValueOffset(v Value, delta float64) (Value, bool) {
	switch v.kind {
	case valueInteger:
		return NumberValue(v.label, float64(v.integer)+delta), true
	case valueNumber:
		return NumberValue(v.label, v.number+delta), true
	case valueTime:
		return TimeValue(v.label, v.timestamp.Add(time.Duration(delta*float64(time.Second))), v.timeUnit), true
	default:
		return Value{}, false
	}
}

func stripAnnotationControlMods(m Mark) Mark {
	return stripMarkMods(
		m,
		modAnnotationDataOffset,
		modAnnotationCollision,
		modAnnotationPriority,
		modAnnotationDeclutterLatest,
		modAnnotationDeclutterDistance,
	)
}

func stripAnnotationAttachmentMods(m Mark) Mark {
	return stripMarkMods(
		m,
		modAnnotation,
		modAnnotationOverflow,
		modAnnotationOffset,
		modAnnotationDataOffset,
		modAnnotationCollision,
		modAnnotationPriority,
		modAnnotationDeclutterLatest,
		modAnnotationDeclutterDistance,
	)
}

func annotationAnchorMark(m Mark) (Mark, bool) {
	dx, dy, ok := annotationDataOffset(m)
	if !ok {
		return Mark{}, false
	}
	xDim, okX := findDim(m.dims, dimX)
	yDim, okY := findDim(m.dims, dimY)
	if !okX || !okY {
		return Mark{}, false
	}
	xv, okX := addValueOffset(xDim.value, dx)
	yv, okY := addValueOffset(yDim.value, dy)
	if !okX || !okY {
		return Mark{}, false
	}
	anchor := PointMark(X(xv), Y(yv))
	for _, mod := range m.mods {
		switch mod.kind {
		case modAnnotation, modAnnotationOverflow, modAnnotationOffset:
			anchor.mods = append(anchor.mods, mod)
		}
	}
	anchor = anchor.Opacity(0).AccessibilityHidden(true).ExcludeFromLegend()
	return anchor, true
}

func stripAnnotationViewMods(m Mark) Mark {
	return stripMarkMods(m, modAnnotation, modAnnotationOverflow, modAnnotationOffset)
}

func resolvedStyleEntry(entries []StyleScaleEntry, key string) (StyleScaleEntry, bool) {
	for _, entry := range entries {
		if entry.Key == key {
			return entry, true
		}
	}
	return StyleScaleEntry{}, false
}

func resolvedSymbolEntry(entries []SymbolScaleEntry, key string) (SymbolScaleEntry, bool) {
	for _, entry := range entries {
		if entry.Key == key {
			return entry, true
		}
	}
	return SymbolScaleEntry{}, false
}

func resolvedLineStyleEntry(entries []LineStyleScaleEntry, key string) (LineStyleScaleEntry, bool) {
	for _, entry := range entries {
		if entry.Key == key {
			return entry, true
		}
	}
	return LineStyleScaleEntry{}, false
}

func resolvedSymbolSizeEntry(entries []SymbolSizeScaleEntry, key string) (SymbolSizeScaleEntry, bool) {
	for _, entry := range entries {
		if entry.Key == key {
			return entry, true
		}
	}
	return SymbolSizeScaleEntry{}, false
}

func (b *chartBuilder) resolveLegendExcludedMark(m Mark) Mark {
	if len(m.children) > 0 {
		children := make([]Mark, len(m.children))
		for i, child := range m.children {
			children[i] = b.resolveLegendExcludedMark(child)
		}
		m.children = children
	}
	if !hasMarkMod(m, modExcludeFromLegend) {
		return m
	}
	mods := make([]markMod, 0, len(m.mods))
	for _, mod := range m.mods {
		switch mod.kind {
		case modExcludeFromLegend:
			continue
		case modForegroundStyleBy:
			if entry, ok := resolvedStyleEntry(b.styleScale.entries, mod.value); ok {
				mods = append(mods, markMod{kind: modForegroundStyle, color: entry.Color})
			}
		case modSymbolBy:
			if entry, ok := resolvedSymbolEntry(b.symbolScale.entries, mod.value); ok {
				mods = append(mods, markMod{kind: modSymbol, intV: int32(entry.Symbol)})
			}
		case modLineStyleBy:
			if entry, ok := resolvedLineStyleEntry(b.lineStyleScale.entries, mod.value); ok {
				mods = append(mods, markMod{kind: modLineStyle, floatV: entry.Style.Width, dash: append([]float64(nil), entry.Style.Dash...)})
			}
		case modSymbolSizeBy:
			if entry, ok := resolvedSymbolSizeEntry(b.symbolSizeScale.entries, mod.value); ok {
				mods = append(mods, markMod{kind: modSymbolSize, floatV: entry.Size})
			}
		default:
			mods = append(mods, mod)
		}
	}
	m.mods = mods
	return m
}

func (b *chartBuilder) declutterMarks(marks []Mark) []Mark {
	processed := make([]Mark, len(marks))
	for i, m := range marks {
		if len(m.children) > 0 {
			m.children = b.declutterMarks(copyMarkChildren(m.children))
		}
		processed[i] = m
	}
	keepAnnotation := make([]bool, len(processed))
	seen := 0
	state := &annotationCoordState{
		xCategories: map[string]float64{},
		yCategories: map[string]float64{},
	}
	var kept []keptAnnotation
	defaultMinX, defaultMinY := b.collisionThresholds()
	for i := len(processed) - 1; i >= 0; i-- {
		m := processed[i]
		keep := hasMarkMod(m, modAnnotation)
		if !keep {
			continue
		}
		if hasMarkMod(m, modAnnotation) {
			if limit, ok := annotationDeclutterLimit(m); ok {
				seen++
				if seen > limit {
					keep = false
				}
			}
			if keep {
				minX, minY, hasDistance := annotationDeclutterDistance(m)
				collision := annotationCollisionMode(m)
				if collision != AnnotationCollisionAutomatic && !hasDistance {
					minX, minY = defaultMinX, defaultMinY
					hasDistance = true
				}
				if hasDistance {
					if point, ok := annotationPointForMark(m, state); ok {
						overlaps := annotationOverlapIndices(point, kept, minX, minY)
						if len(overlaps) > 0 {
							switch collision {
							case AnnotationCollisionKeepPriority:
								priority := annotationPriority(m)
								replace := true
								for _, idx := range overlaps {
									if priority <= kept[idx].priority {
										replace = false
										break
									}
								}
								if !replace {
									keep = false
									break
								}
								for j := len(overlaps) - 1; j >= 0; j-- {
									idx := overlaps[j]
									keepAnnotation[kept[idx].index] = false
									kept = append(kept[:idx], kept[idx+1:]...)
								}
								kept = append(kept, keptAnnotation{point: point, index: i, priority: priority})
							default:
								keep = false
							}
						} else {
							kept = append(kept, keptAnnotation{point: point, index: i, priority: annotationPriority(m)})
						}
					}
				}
			}
		}
		keepAnnotation[i] = keep
	}
	out := make([]Mark, 0, len(processed)*2)
	for i, m := range processed {
		if hasMarkMod(m, modAnnotation) && !keepAnnotation[i] {
			m = stripAnnotationViewMods(m)
		}
		if keepAnnotation[i] && hasMarkMod(m, modAnnotationDataOffset) {
			if anchor, ok := annotationAnchorMark(m); ok {
				out = append(out, stripAnnotationControlMods(stripAnnotationAttachmentMods(m)))
				out = append(out, stripAnnotationControlMods(anchor))
				continue
			}
		}
		out = append(out, stripAnnotationControlMods(m))
	}
	return out
}

func (b *chartBuilder) preparedMarks() []Mark {
	marks := append([]Mark(nil), b.marks...)
	marks = b.declutterMarks(marks)
	for i, mark := range marks {
		marks[i] = b.resolveLegendExcludedMark(mark)
	}
	return marks
}

func (b *chartBuilder) toSpec() chartSpec {
	spec := chartSpec{
		XScaleType: b.xScaleType.toSpec(),
		YScaleType: b.yScaleType.toSpec(),
		ScrollAxes: int32(b.scrollAxes),
	}
	if len(b.marks) > 0 {
		marks := b.preparedMarks()
		spec.Marks = make([]markSpec, len(marks))
		for i, mark := range marks {
			spec.Marks[i] = mark.toSpec()
		}
	}
	if b.xDomain != nil {
		d := b.xDomain.toSpec()
		spec.XDomain = &d
	}
	if b.yDomain != nil {
		d := b.yDomain.toSpec()
		spec.YDomain = &d
	}
	if b.xRange != nil {
		r := b.xRange.toSpec()
		spec.XRange = &r
	}
	if b.yRange != nil {
		r := b.yRange.toSpec()
		spec.YRange = &r
	}
	if b.xAxis != nil {
		cfg := b.xAxis.toSpec()
		spec.XAxis = &cfg
	}
	if b.yAxis != nil {
		cfg := b.yAxis.toSpec()
		spec.YAxis = &cfg
	}
	if b.xAxisLabel != nil {
		label := b.xAxisLabel.toSpec()
		spec.XAxisLabel = &label
	}
	if b.yAxisLabel != nil {
		label := b.yAxisLabel.toSpec()
		spec.YAxisLabel = &label
	}
	if len(b.xAxisStyle) > 0 {
		style := axisStyleSpec{Entries: make([]axisStyleEntrySpec, len(b.xAxisStyle))}
		for i, entry := range b.xAxisStyle {
			style.Entries[i] = entry.toSpec()
		}
		spec.XAxisStyle = &style
	}
	if len(b.yAxisStyle) > 0 {
		style := axisStyleSpec{Entries: make([]axisStyleEntrySpec, len(b.yAxisStyle))}
		for i, entry := range b.yAxisStyle {
			style.Entries[i] = entry.toSpec()
		}
		spec.YAxisStyle = &style
	}
	if len(b.styleScale.entries) > 0 || b.styleScale.scaleType != nil {
		scale := foregroundStyleScaleSpec{}
		if len(b.styleScale.entries) > 0 {
			scale.Entries = make([]styleScaleSpec, len(b.styleScale.entries))
			for i, entry := range b.styleScale.entries {
				scale.Entries[i] = entry.toSpec()
			}
		}
		if b.styleScale.scaleType != nil {
			value := b.styleScale.scaleType.toSpec()
			scale.ScaleType = &value
		}
		spec.StyleScale = &scale
	}
	if len(b.symbolScale.entries) > 0 {
		scale := symbolScaleSpec{Entries: make([]symbolScaleEntrySpec, len(b.symbolScale.entries))}
		for i, entry := range b.symbolScale.entries {
			scale.Entries[i] = entry.toSpec()
		}
		spec.SymbolScale = &scale
	}
	if len(b.lineStyleScale.entries) > 0 {
		scale := lineStyleScaleSpec{Entries: make([]lineStyleScaleEntrySpec, len(b.lineStyleScale.entries))}
		for i, entry := range b.lineStyleScale.entries {
			scale.Entries[i] = entry.toSpec()
		}
		spec.LineStyleScale = &scale
	}
	if len(b.symbolSizeScale.entries) > 0 || b.symbolSizeScale.scaleType != nil {
		scale := symbolSizeScaleSpec{}
		if len(b.symbolSizeScale.entries) > 0 {
			scale.Entries = make([]symbolSizeScaleEntrySpec, len(b.symbolSizeScale.entries))
			for i, entry := range b.symbolSizeScale.entries {
				scale.Entries[i] = entry.toSpec()
			}
		}
		if b.symbolSizeScale.scaleType != nil {
			value := b.symbolSizeScale.scaleType.toSpec()
			scale.ScaleType = &value
		}
		spec.SymbolSizeScale = &scale
	}
	if b.legend != nil {
		cfg := b.legend.toSpec()
		spec.Legend = &cfg
	}
	if len(b.plot) > 0 {
		spec.Plot = make([]plotStyleSpec, len(b.plot))
		for i, opt := range b.plot {
			spec.Plot[i] = opt.toSpec()
		}
	}
	if b.scrollPosition != nil {
		pos := b.scrollPosition.toSpec()
		spec.ScrollPosition = &pos
	}
	if b.visibleLength != nil {
		v := *b.visibleLength
		spec.VisibleLength = &v
	}
	spec.XSelection = stateSpec(b.xSelection)
	spec.XSelectionRange = stateSpec(b.xSelectionRange)
	spec.YSelection = stateSpec(b.ySelection)
	spec.YSelectionRange = stateSpec(b.ySelectionRange)
	spec.AngleSelection = stateSpec(b.angleSelection)
	if b.scrollTarget != nil {
		target := b.scrollTarget.toSpec()
		spec.ScrollTarget = &target
	}
	spec.XScrollBinding = stateSpec(b.xScrollBinding)
	spec.YScrollBinding = stateSpec(b.yScrollBinding)
	if b.xVisibleLength != nil {
		value := b.xVisibleLength.toSpec()
		spec.XVisibleLength = &value
	} else if b.visibleLength != nil {
		value := VisibleDomainNumeric(*b.visibleLength).toSpec()
		spec.XVisibleLength = &value
	}
	if b.yVisibleLength != nil {
		value := b.yVisibleLength.toSpec()
		spec.YVisibleLength = &value
	}
	if len(b.overlays) > 0 {
		spec.Overlays = make([]proxyLayerSpec, len(b.overlays))
		for i, overlay := range b.overlays {
			spec.Overlays[i] = overlay.toSpec()
		}
	}
	if len(b.backgrounds) > 0 {
		spec.Backgrounds = make([]proxyLayerSpec, len(b.backgrounds))
		for i, background := range b.backgrounds {
			spec.Backgrounds[i] = background.toSpec()
		}
	}
	if b.gesture != nil {
		gesture := b.gesture.toSpec()
		spec.Gesture = &gesture
	}
	return spec
}
